49	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
52	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
53	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
54	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
55	import org.springframework.samples.petclinic.service.ClinicService;
56	import org.springframework.security.access.prepost.PreAuthorize;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
74	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
75	
76	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
77	    private static final int MAX_OWNERS_PER_CITY = 50;
78	
79	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
80	    private static final int MAX_OWNERS_PER_DAY = 100;
81	
82	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
83	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    private final TelephoneNormalizer telephoneNormalizer;
94	
95	    private final AddressNormalizer addressNormalizer;
96	
97	    private final EmailNormalizer emailNormalizer;
98	
99	    private final IdentityKeyResolver identityKeyResolver;
100	
101	    public OwnerRestControllerV1(ClinicService clinicService,
102	                                 OwnerMapper ownerMapper,
103	                                 PetMapper petMapper,
104	                                 VisitMapper visitMapper,
105	                                 TelephoneNormalizer telephoneNormalizer,
106	                                 AddressNormalizer addressNormalizer,
107	                                 EmailNormalizer emailNormalizer,
108	                                 IdentityKeyResolver identityKeyResolver) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	        this.telephoneNormalizer = telephoneNormalizer;
114	        this.addressNormalizer = addressNormalizer;
115	        this.emailNormalizer = emailNormalizer;
116	        this.identityKeyResolver = identityKeyResolver;
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
122	        Collection<Owner> owners;
123	        if (lastName != null) {
124	            owners = this.clinicService.findOwnerByLastName(lastName);
125	        } else {
126	            owners = this.clinicService.findAllOwners();
127	        }
128	        if (owners.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        owners.forEach(this::populateHouseholdMemberCount);
132	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
133	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        populateHouseholdMemberCount(owner);
144	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    /**
148	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
149	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
150	     * by the mapper alone.
151	     *
152	     * @param owner the owner to map
153	     * @return the owner DTO carrying its identity key
154	     */
155	    private OwnerDto toOwnerDto(Owner owner) {
156	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
157	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
158	        return ownerDto;
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Transactional
163	    @Override
164	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
165	        normalizeAndValidate(ownerFieldsDto);
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        owner.setCustomerCode(identityKeyResolver.deriveCustomerCode(owner));
169	        owner.setNamesakeCount(countNamesakes(owner));
170	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
171	        assignHouseholdId(owner, ownerFieldsDto);
172	        requireUniqueIdentity(owner);
173	        this.clinicService.saveOwner(owner);
174	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
175	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
176	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
177	        populateHouseholdMemberCount(owner);
178	        OwnerDto ownerDto = toOwnerDto(owner);
179	        headers.setLocation(UriComponentsBuilder.newInstance()
180	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
181	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
182	    }
183	
184	    /**
185	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
186	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
187	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
188	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
189	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
190	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
191	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
192	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
193	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
194	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
195	     * assigned (see {@link #requireUniqueIdentity}).
196	     *
197	     * @param ownerFieldsDto the incoming owner payload, mutated in place
198	     * @throws MissingOwnerFieldsException if any required field is missing or blank
199	     */
200	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
201	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
202	        validateRequiredFields(ownerFieldsDto);
203	        validatePostcode(ownerFieldsDto);
204	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
205	        ownerFieldsDto.setTelephone(telephone);
206	        requireCityHasCapacity(ownerFieldsDto.getCity());
207	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
208	        ownerFieldsDto.setRegistrationDate(registrationDate);
209	        requireDailyLimitNotReached(registrationDate);
210	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
211	        ownerFieldsDto.setEmail(email);
212	    }
213	
214	    /**
215	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
216	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
217	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
218	     * later than the current server date is rejected.
219	     *
220	     * @param ownerFieldsDto the incoming owner payload
221	     * @return the effective registration date rolled forward onto a business day
222	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
223	     */
224	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
225	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
226	        if (effective == null) {
227	            effective = LocalDate.now();
228	        }
229	        else if (effective.isAfter(LocalDate.now())) {
230	            throw new FutureRegistrationDateException(
231	                "the registration date must not be later than the current server date");
232	        }
233	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
234	            effective = effective.plusDays(1);
235	        }
236	        return effective;
237	    }
238	
239	    /**
240	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
241	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
242	     * further owner may be created for that day.
243	     *
244	     * @param registrationDate the adjusted business-day registration date of the owner being created
245	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
246	     */
247	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
248	        long createdThatDay = this.clinicService.findAllOwners().stream()
249	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
250	            .count();
251	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
252	            throw new DailyOwnerLimitExceededException(
253	                "the maximum number of owners for today has already been reached");
254	        }
255	    }
256	
257	    /**
258	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
259	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
260	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
261	     * reflects only owners that predate it.
262	     *
263	     * @param registrationDate the adjusted business-day registration date of the owner being created
264	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
265	     */
266	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
267	        long createdThatDay = this.clinicService.findAllOwners().stream()
268	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
269	            .count();
270	        return createdThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
271	    }
272	
273	    /**
274	     * Counts how many existing owners already share the given owner's first and last name, compared
275	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
276	     * create; it is zero when the owner's name is unique.
277	     *
278	     * @param owner the newly mapped owner about to be saved
279	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
280	     */
281	    private int countNamesakes(Owner owner) {
282	        String firstName = owner.getFirstName();
283	        String lastName = owner.getLastName();
284	        return (int) this.clinicService.findAllOwners().stream()
285	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
286	                && lastName.equalsIgnoreCase(existing.getLastName()))
287	            .count();
288	    }
289	
290	    /**
291	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
292	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
293	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
294	     *
295	     * @param ownerFieldsDto the owner payload to validate
296	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
297	     */
298	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
299	        List<String> missingFields = new ArrayList<>();
300	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
301	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
302	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
303	        requireText(missingFields, "city", ownerFieldsDto.getCity());
304	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
305	        if (!missingFields.isEmpty()) {
306	            throw new MissingOwnerFieldsException(missingFields);
307	        }
308	    }
309	
310	    private void requireText(List<String> missingFields, String fieldName, String value) {
311	        if (value == null || value.isBlank()) {
312	            missingFields.add(fieldName);
313	        }
314	    }
315	
316	    /**
317	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
318	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
319	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
320	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
321	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
322	     *
323	     * @param ownerFieldsDto the incoming owner payload
324	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
325	     */
326	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
327	        String postcode = ownerFieldsDto.getPostcode();
328	        if (postcode == null) {
329	            return;
330	        }
331	        Region region = Region.forCity(ownerFieldsDto.getCity());
332	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
333	            throw new InvalidPostcodeException(
334	                "postcode " + postcode + " is not valid for the city's region " + region.name());
335	        }
336	    }
337	
338	    /**
339	     * Rejects creating an owner whose whole derived {@code identityKey} (see
340	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner. This is the single, consolidated
341	     * duplicate check: the former separate telephone, email and household rules are all expressed through this one key,
342	     * so an owner is a duplicate only when its normalized telephone, email and {@code householdId} all match another
343	     * owner's. It runs after the household id has been assigned, so the key reflects the household the owner belongs to.
344	     *
345	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
346	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
347	     */
348	    private void requireUniqueIdentity(Owner owner) {
349	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
350	        boolean inUse = this.clinicService.findAllOwners().stream()
351	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
352	        if (inUse) {
353	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
354	        }
355	    }
356	
357	    /**
358	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
359	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
360	     *
361	     * @param city the city of the owner being created
362	     * @throws OwnerCityFullException if the city already contains 50 or more owners
363	     */
364	    private void requireCityHasCapacity(String city) {
365	        long cityOwners = this.clinicService.findAllOwners().stream()
366	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
367	            .count();
368	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
369	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
370	        }
371	    }
372	
373	    /**
374	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
375	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
376	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
377	     * incidental formatting differences and abbreviation variants do not affect membership.
378	     *
379	     * @param ownerFieldsDto the incoming owner payload
380	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
381	     *         them; empty when none match
382	     */
383	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
384	        String lastName = identityKeyResolver.collapseWhitespace(ownerFieldsDto.getLastName());
385	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
386	        return this.clinicService.findAllOwners().stream()
387	            .filter(existing -> identityKeyResolver.collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
388	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
389	            .toList();
390	    }
391	
392	    /**
393	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
394	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
395	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
396	     * identifier is derived deterministically from the household's last name and address (see
397	     * {@link IdentityKeyResolver#deriveHouseholdId}), so every member of the same household resolves to the same stable
398	     * value regardless of creation order. Existing members that predate the feature and still lack the identifier are
399	     * backfilled (see {@link #backfillHouseholdMembers}) so the whole household shares it.
400	     *
401	     * @param owner          the newly mapped owner about to be saved
402	     * @param ownerFieldsDto the incoming owner payload
403	     */
404	    private void assignHouseholdId(Owner owner, OwnerFieldsDto ownerFieldsDto) {
405	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
406	            return;
407	        }
408	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
409	        if (members.isEmpty()) {
410	            return;
411	        }
412	        String householdId =
413	            identityKeyResolver.deriveHouseholdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
414	        owner.setHouseholdId(householdId);
415	        backfillHouseholdMembers(householdId, members);
416	    }
417	
418	    /**
419	     * Stamps the shared {@code householdId} onto the existing members of a household that do not already carry it,
420	     * persisting each one that changes. Members that predate the feature (and so still lack the identifier) are brought
421	     * into line so the whole household shares the single value; members that already carry it are left untouched.
422	     *
423	     * @param householdId the shared household identifier
424	     * @param members     the existing owners in the household
425	     */
426	    private void backfillHouseholdMembers(String householdId, List<Owner> members) {
427	        for (Owner member : members) {
428	            if (!householdId.equals(member.getHouseholdId())) {
429	                member.setHouseholdId(householdId);
430	                this.clinicService.saveOwner(member);
431	            }
432	        }
433	    }
434	
435	    /**
436	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
437	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
438	     * household is counted as a household of one.
439	     *
440	     * @param owner the owner whose household size should be resolved
441	     */
442	    private void populateHouseholdMemberCount(Owner owner) {
443	        String householdId = owner.getHouseholdId();
444	        if (householdId == null) {
445	            owner.setHouseholdMemberCount(1);
446	            return;
447	        }
448	        long members = this.clinicService.findAllOwners().stream()
449	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
450	            .count();
451	        owner.setHouseholdMemberCount((int) members);
452	    }
453	
454	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
455	    @Override
456	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
457	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
458	        if (currentOwner == null) {
459	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
460	        }
461	        validatePostcode(ownerFieldsDto);
462	        currentOwner.setAddress(ownerFieldsDto.getAddress());
463	        currentOwner.setCity(ownerFieldsDto.getCity());
464	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
465	        currentOwner.setLastName(ownerFieldsDto.getLastName());
466	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
467	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
468	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
469	        this.clinicService.saveOwner(currentOwner);
470	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
471	    }
472	
473	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
474	    @Transactional
475	    @Override
476	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
477	        Owner owner = this.clinicService.findOwnerById(ownerId);
478	        if (owner == null) {
479	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
480	        }
481	        this.clinicService.deleteOwner(owner);
482	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
483	    }
484	
485	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
486	    @Override
487	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
488	        Owner owner = this.clinicService.findOwnerById(ownerId);
489	        if (owner == null) {
490	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
491	        }
492	        HttpHeaders headers = new HttpHeaders();
493	        Pet pet = petMapper.toPet(petFieldsDto);
494	        owner.setId(ownerId);
495	        pet.setOwner(owner);
496	        pet.getType().setName(null);
497	        this.clinicService.savePet(pet);
498	        PetDto petDto = petMapper.toPetDto(pet);
499	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
500	            .buildAndExpand(pet.getId()).toUri());
501	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
502	    }
503	
504	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
505	    @Override
506	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
507	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
508	        if (currentOwner != null) {
509	            Pet currentPet = this.clinicService.findPetById(petId);
510	            if (currentPet != null) {
511	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
