1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
9	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
10	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
11	import org.springframework.stereotype.Component;
12	
13	/**
14	 * Derives the stable identifiers an owner is matched on: the shared household id (a pure function of the household's
15	 * last name and address) and the single {@code identityKey} that all duplicate detection is expressed through. Keeping
16	 * this here (rather than in {@link OwnerMapper} or the REST controller) mirrors {@link LocalityResolver} and
17	 * {@link MembershipLevelResolver} and gives owner-identity derivation a single home. Unlike those two it collaborates
18	 * with the field normalizers, so it is a Spring component rather than a static utility.
19	 */
20	@Component
21	public class IdentityKeyResolver {
22	
23	    private final AddressNormalizer addressNormalizer;
24	
25	    private final TelephoneNormalizer telephoneNormalizer;
26	
27	    private final EmailNormalizer emailNormalizer;
28	
29	    public IdentityKeyResolver(AddressNormalizer addressNormalizer,
30	                               TelephoneNormalizer telephoneNormalizer,
31	                               EmailNormalizer emailNormalizer) {
32	        this.addressNormalizer = addressNormalizer;
33	        this.telephoneNormalizer = telephoneNormalizer;
34	        this.emailNormalizer = emailNormalizer;
35	    }
36	
37	    /**
38	     * Derives the owner's {@code identityKey}, the single value all duplicate detection is expressed through. It is
39	     * formatted {@code <normalizedTelephone>|<email or empty>|<householdId or empty>}, joining the canonical E.164
40	     * telephone (see {@link TelephoneNormalizer#canonicalize}), the normalized email (see
41	     * {@link EmailNormalizer#normalize}, empty when the owner has none) and the shared {@code householdId} (empty when
42	     * the owner belongs to no household). Because the telephone is part of the key, two owners that differ only in
43	     * telephone — such as two members of the same household — have different keys; only owners whose whole key matches
44	     * are duplicates.
45	     *
46	     * @param owner the owner whose identity key should be derived
47	     * @return the owner's identity key
48	     */
49	    public String deriveIdentityKey(Owner owner) {
50	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
51	        String email = emailNormalizer.normalize(owner.getEmail());
52	        String householdId = owner.getHouseholdId();
53	        return telephone
54	            + "|" + (email == null || email.isBlank() ? "" : email)
55	            + "|" + (householdId == null ? "" : householdId);
56	    }
57	
58	    /**
59	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
60	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
61	     * of those fields, it is identical for every owner in the same household and never changes over time.
62	     *
63	     * @param lastName the household's last name
64	     * @param address  the household's address
65	     * @return the household identifier
66	     */
67	    public String deriveHouseholdId(String lastName, String address) {
68	        String key = collapseWhitespace(lastName).toLowerCase()
69	            + "\n" + addressNormalizer.normalize(address).toLowerCase();
70	        return "HH-" + upperHexDigest(key, 12);
71	    }
72	
73	    /**
74	     * Derives an owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>}. {@code REGION} is the region code
75	     * derived from the owner's postcode (see {@link Region#forPostcode}), falling back to {@link LocalityResolver#UNKNOWN}
76	     * when the postcode maps to no known region; {@code HASH8} is the first 8 upper-case hex characters of the SHA-256
77	     * digest of the normalized telephone (see {@link TelephoneNormalizer#canonicalize}) concatenated with the owner's
78	     * last name (e.g. {@code NSW-1A2B3C4D}). Being a pure function of the postcode, telephone and last name it carries
79	     * no sequence number and is stable for a given owner.
80	     *
81	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
82	     * @return the generated customer code
83	     */
84	    public String deriveCustomerCode(Owner owner) {
85	        Region region = Region.forPostcode(owner.getPostcode());
86	        String regionCode = region == null ? LocalityResolver.UNKNOWN : region.name();
87	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
88	        String hash8 = upperHexDigest(telephone + owner.getLastName(), 8);
89	        return regionCode + "-" + hash8;
90	    }
91	
92	    /**
93	     * Returns the first {@code chars} upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of
94	     * {@code value}. Shared by {@link #deriveHouseholdId} and {@link #deriveCustomerCode} so both express the same
95	     * hashing in one place.
96	     *
97	     * @param value the value to hash
98	     * @param chars the number of leading hex characters to return
99	     * @return the leading upper-case hex characters of the digest
100	     */
101	    private String upperHexDigest(String value, int chars) {
102	        try {
103	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
104	            StringBuilder hex = new StringBuilder();
105	            for (byte b : digest) {
106	                hex.append(String.format("%02X", b));
107	            }
108	            return hex.substring(0, chars);
109	        } catch (NoSuchAlgorithmException ex) {
110	            throw new IllegalStateException("SHA-256 is not available", ex);
111	        }
112	    }
113	
114	    /**
115	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
116	     * space. Case is deliberately preserved here; callers apply their own case handling ({@link #deriveHouseholdId}
117	     * lower-cases the result, while household matching compares it case-insensitively).
118	     *
119	     * @param value the raw field value, may be {@code null}
120	     * @return the whitespace-collapsed value, or an empty string when {@code null}
121	     */
122	    public String collapseWhitespace(String value) {
123	        if (value == null) {
124	            return "";
125	        }
126	        return value.strip().replaceAll("\\s+", " ");
127	    }
128	}
